(() => {
 const root=document.getElementById("haView"); if(!root || root.dataset.ready==="1") return; root.dataset.ready="1";
 const topics=[
  ["Anatomy & Physiology","10%","Body systems: integumentary, skeletal, muscular, nervous, endocrine, blood, cardiovascular, lymphatic/immunity, digestive, respiratory, urinary, reproductive systems and growth.","शरीरका प्रणाली, तिनको बनावट, काम, रक्तसञ्चार, श्वासप्रश्वास, पाचन, उत्सर्जन, प्रजनन र वृद्धि-विकास।"],
  ["Community Health","25%","Health education and promotion; environmental health; PHC and family health; epidemiology and disease control; nutrition; community diagnosis; health management.","स्वास्थ्य शिक्षा, वातावरणीय स्वास्थ्य, प्राथमिक स्वास्थ्य सेवा, परिवार स्वास्थ्य, महामारी विज्ञान, रोग नियन्त्रण, पोषण, समुदाय निदान र स्वास्थ्य व्यवस्थापन।"],
  ["General Medicine","25%","Clinical methods; systemic diseases; pediatrics and neonatology; skin diseases; sexually transmitted infections; psychiatry.","इतिहास लिने र शारीरिक परीक्षण, विभिन्न प्रणालीका रोग, बाल तथा नवजात स्वास्थ्य, छालाका रोग, यौनसञ्चारित संक्रमण र मानसिक स्वास्थ्य।"],
  ["Pharmacology & Pharmacy","10%","Clinical pharmacology, common drug groups, rational drug use, pharmacokinetics/dynamics, dispensing, labeling, inventory and preparations.","औषधिको प्रभाव र शरीरमा हुने प्रक्रिया, सामान्य औषधि समूह, विवेकपूर्ण औषधि प्रयोग, भण्डारण, लेबल, वितरण र औषधि तयारी।"],
  ["General Surgery","25%","Basic surgery; first aid and emergency care; obstetrics and gynecology; eye, ENT and oral health.","सामान्य शल्यचिकित्सा, प्राथमिक उपचार, आकस्मिक सेवा, प्रसूति तथा स्त्रीरोग, आँखा, कान-नाक-घाँटी र मुख स्वास्थ्य।"],
  ["Clinical Pathology","5%","Biochemistry, microbiology, parasitology, hematology, blood collection and common laboratory principles.","जैवरसायन, सूक्ष्मजीव विज्ञान, परजीवी विज्ञान, रक्तविज्ञान, रगत संकलन र प्रयोगशाला परीक्षणका आधार।"]
 ];
 const notes=[
 ["1. Clinical history taking","A structured history includes presenting complaint, history of present illness, past medical/surgical history, medication and allergy history, family and social history, and review of systems. Use open questions first, then clarify onset, duration, severity, associated symptoms and red flags.","व्यवस्थित इतिहासमा मुख्य समस्या, हालको रोगको विवरण, पुराना रोग/शल्यक्रिया, औषधि तथा एलर्जी, पारिवारिक/सामाजिक इतिहास र प्रणालीगत समीक्षा पर्छ। पहिले खुला प्रश्न सोध्नुहोस्; त्यसपछि सुरु भएको समय, अवधि, गम्भीरता र चेतावनी संकेत बुझ्नुहोस्।"],
 ["2. General physical examination","Assess general appearance, consciousness, hydration, pallor, jaundice, cyanosis, clubbing, edema, lymph nodes and vital signs. Interpret findings in context; repeat unexpected measurements and document units.","सामान्य परीक्षणमा देखावट, चेतना, पानीको अवस्था, रक्तअल्पताको फिक्कापन, जन्डिस, नीलोपन, औँलाको clubbing, सुन्निनु, lymph node र vital signs जाँचिन्छ। असामान्य नतिजा पुनः जाँचेर एकाइ सहित लेख्नुहोस्।"],
 ["3. Vital signs","Core vital signs include temperature, pulse, respiratory rate, blood pressure and oxygen saturation when indicated. Correct cuff size, patient position, rest period and technique improve accuracy.","मुख्य vital signs तापक्रम, नाडी, श्वासदर, रक्तचाप र आवश्यकताअनुसार oxygen saturation हुन्। सही cuff, बिरामीको अवस्था, आराम अवधि र विधिले मापन शुद्ध बनाउँछ।"],
 ["4. Cardiovascular overview","The heart pumps blood through pulmonary and systemic circulation. Assess chest pain, dyspnea, palpitations, syncope, edema and relevant risk factors. Acute chest pain with instability requires urgent emergency assessment.","मुटुले pulmonary र systemic circulation मार्फत रगत पम्प गर्छ। छाती दुखाइ, सास फेर्न गाह्रो, धड्कन, बेहोसी, सुन्निनु र जोखिम जाँच्नुहोस्। अस्थिर अवस्थासहितको तीव्र छाती दुखाइमा तुरुन्त आकस्मिक मूल्याङ्कन आवश्यक हुन्छ।"],
 ["5. Respiratory overview","Assess cough, sputum, breathlessness, wheeze, chest pain and respiratory effort. Respiratory rate and oxygen saturation help assess severity. Severe distress, cyanosis or altered consciousness are emergency signs.","खोकी, खकार, सास फेर्न गाह्रो, wheeze, छाती दुखाइ र श्वास प्रयास जाँच्नुहोस्। श्वासदर र oxygen saturation ले गम्भीरता बुझ्न मद्दत गर्छ। अत्यधिक सास कष्ट, नीलोपन वा चेतना परिवर्तन आकस्मिक संकेत हुन्।"],
 ["6. Gastrointestinal and hepatic symptoms","Ask about appetite, nausea, vomiting, abdominal pain, bowel habit, blood in stool, jaundice and weight change. Severe abdominal pain, persistent vomiting, GI bleeding or peritonism need urgent evaluation.","भोक, वाकवाकी, बान्ता, पेट दुखाइ, दिसाको बानी, दिसामा रगत, जन्डिस र तौल परिवर्तन सोध्नुहोस्। तीव्र पेट दुखाइ, लगातार बान्ता, पाचननलीबाट रक्तस्राव वा peritonism मा तत्काल जाँच चाहिन्छ।"],
 ["7. Diabetes mellitus","Diabetes is a metabolic disorder characterized by persistent hyperglycemia due to impaired insulin secretion, insulin action, or both. Diagnosis uses validated plasma glucose or HbA1c criteria; symptoms alone are insufficient.","मधुमेह insulin उत्पादन वा काममा समस्या हुँदा रगतमा glucose लगातार बढ्ने अवस्था हो। निदानका लागि मान्य plasma glucose वा HbA1c मापदण्ड प्रयोग हुन्छ; लक्षण मात्र पर्याप्त हुँदैन।"],
 ["8. Hypertension","Hypertension is persistently elevated blood pressure. Confirm with properly performed repeated measurements and follow current national guidance. Assess cardiovascular risk, adherence, lifestyle and evidence of target-organ damage.","उच्च रक्तचाप भनेको रक्तचाप लगातार बढिरहने अवस्था हो। सही विधिले पटक-पटक मापन गरी हालको राष्ट्रिय निर्देशिका अनुसार पुष्टि गर्नुपर्छ। मुटु-रक्तनली जोखिम, औषधि नियमितता, जीवनशैली र अंगमा क्षति जाँच्नुहोस्।"],
 ["9. Pediatric assessment","Assess age-specific growth, feeding, immunization, development, hydration, danger signs and caregiver concerns. Use the current national IMNCI/IMCI chart and refer urgently for general danger signs.","बालबालिकामा उमेरअनुसार वृद्धि, खाना, खोप, विकास, पानीको अवस्था, खतरा संकेत र अभिभावकको चिन्ता जाँच्नुहोस्। हालको राष्ट्रिय IMNCI/IMCI चार्ट प्रयोग गरी सामान्य खतरा संकेत भए तुरुन्त referral गर्नुहोस्।"],
 ["10. Neonatal danger signs","Poor feeding, convulsions, fast or difficult breathing, fever or hypothermia, reduced movement and severe jaundice may indicate serious neonatal illness. Stabilize within scope and arrange urgent referral.","दूध नखानु, दौरा, छिटो वा गाह्रो श्वास, ज्वरो वा शरीर चिसो हुनु, कम चल्नु र गम्भीर जन्डिस नवजात शिशुको गम्भीर रोगका संकेत हुन सक्छन्। आफ्नो कार्यक्षेत्रभित्र प्रारम्भिक स्थिरीकरण गरी तुरुन्त referral गर्नुहोस्।"],
 ["11. Infection prevention","Apply standard precautions to every patient: hand hygiene, risk-based PPE, respiratory hygiene, safe injection practice, sharps safety, environmental cleaning and correct reprocessing of reusable equipment.","हरेक बिरामीमा standard precautions अपनाउनुहोस्: हात सफा, जोखिमअनुसार PPE, श्वास स्वच्छता, सुरक्षित injection, धारिलो वस्तु सुरक्षा, वातावरण सफाइ र पुनःप्रयोग हुने उपकरणको सही प्रशोधन।"],
 ["12. Rational medicine use","Choose medicines according to a valid indication, patient factors, evidence, dose, route, duration, contraindications and interactions. Check allergies, explain use, document and monitor adverse effects. Avoid unnecessary antibiotics.","औषधि स्पष्ट कारण, बिरामीको अवस्था, प्रमाण, मात्रा, दिने बाटो, अवधि, निषेध र interaction हेरेर छान्नुहोस्। एलर्जी जाँच्नुहोस्, प्रयोग बुझाउनुहोस्, अभिलेख राख्नुहोस् र adverse effect निगरानी गर्नुहोस्। अनावश्यक antibiotic नदिनुहोस्।"],
 ["13. First aid and ABCDE","For an acutely ill patient, assess Airway, Breathing, Circulation, Disability and Exposure while calling for help. Treat life-threatening problems first, monitor continuously and arrange transfer according to protocol.","गम्भीर बिरामीमा सहयोग बोलाउँदै Airway, Breathing, Circulation, Disability र Exposure क्रमशः मूल्याङ्कन गर्नुहोस्। ज्यान जोखिमका समस्या पहिले सम्हाल्नुहोस्, निरन्तर निगरानी गरी protocol अनुसार referral/transfer गर्नुहोस्।"],
 ["14. Shock","Shock is life-threatening circulatory failure causing inadequate tissue perfusion. Warning signs can include altered mental status, cool clammy skin, weak rapid pulse and hypotension (often late). Call emergency support and manage per protocol.","Shock भनेको तन्तुमा पर्याप्त रक्तप्रवाह नपुग्ने ज्यान जोखिमको अवस्था हो। चेतना बदलिनु, चिसो पसिनायुक्त छाला, कमजोर छिटो नाडी र रक्तचाप घट्नु (ढिलो संकेत हुन सक्छ) देखिन सक्छ। आकस्मिक सहयोग बोलाई protocol अनुसार व्यवस्थापन गर्नुहोस्।"],
 ["15. Burns","Initial burn care prioritizes stopping the burning process, cooling a thermal burn with cool running water, removing constricting items if safe, covering with a clean non-adherent dressing and assessing airway, circulation and burn severity. Do not apply ice or household substances.","जलनमा पहिले जल्ने प्रक्रिया रोक्नुहोस्, thermal burn लाई चिसो बग्ने पानीले चिस्याउनुहोस्, सुरक्षित भए कसिलो वस्तु हटाउनुहोस् र सफा नटाँसिने dressing लगाउनुहोस्। airway, circulation र गम्भीरता जाँच्नुहोस्। बरफ वा घरेलु पदार्थ नलगाउनुहोस्।"],
 ["16. Obstetric danger signs","Urgent referral is needed for heavy vaginal bleeding, severe headache/visual symptoms, convulsions, severe abdominal pain, fever, difficulty breathing, reduced fetal movement or signs of obstructed labour.","धेरै योनी रक्तस्राव, कडा टाउको दुखाइ/दृष्टि समस्या, दौरा, कडा पेट दुखाइ, ज्वरो, सास कष्ट, बच्चा कम चल्नु वा प्रसव अवरोधका संकेतमा तुरुन्त referral चाहिन्छ।"],
 ["17. STI and respectful care","Provide confidential, non-judgmental assessment. Follow current national STI guidelines for testing, treatment, partner services, counselling and follow-up. Avoid diagnosing solely from symptoms when testing is indicated.","गोपनीयता र भेदभावरहित व्यवहारसहित जाँच गर्नुहोस्। परीक्षण, उपचार, partner service, परामर्श र follow-up का लागि हालको राष्ट्रिय STI निर्देशिका पालना गर्नुहोस्। परीक्षण आवश्यक हुँदा लक्षणका आधारमा मात्र निदान नगर्नुहोस्।"],
 ["18. Community diagnosis","Community diagnosis systematically identifies health problems, determinants, resources and priorities using reliable data, community participation and analysis. Findings should guide a feasible action plan and monitoring indicators.","समुदाय निदानले भरपर्दो तथ्याङ्क, समुदायको सहभागिता र विश्लेषणबाट स्वास्थ्य समस्या, निर्धारक, स्रोत र प्राथमिकता पहिचान गर्छ। नतिजाका आधारमा व्यवहारिक कार्ययोजना र अनुगमन सूचक बनाउनुहोस्।"],
 ["19. Epidemiology basics","Incidence measures new cases in a population at risk over a specified period; prevalence measures all existing cases at a point or over a period. Define numerator, denominator, population and time clearly.","Incidence ले निश्चित अवधिमा जोखिममा रहेको जनसंख्यामा नयाँ केस मापन गर्छ; prevalence ले कुनै समय वा अवधिमा रहेका सबै केस मापन गर्छ। numerator, denominator, जनसंख्या र समय स्पष्ट राख्नुहोस्।"],
 ["20. Safe specimen collection","Use the correct container, patient identification, labeling at the bedside, appropriate collection technique, infection prevention, timely transport and documentation. Reject or clarify unlabeled or mismatched specimens according to policy.","सही container, बिरामी पहिचान, बिरामीकै छेउमा label, उचित संकलन विधि, संक्रमण रोकथाम, समयमै ढुवानी र अभिलेख अपनाउनुहोस्। label नभएको वा विवरण नमिलेको नमुना नीतिअनुसार अस्वीकार वा स्पष्ट गर्नुहोस्।"],
 ["21. Respiratory diseases and assessment","Assess respiratory rate, work of breathing, oxygen saturation and chest findings. Common conditions include upper respiratory infection, pneumonia, asthma and COPD. Red flags include severe breathlessness, cyanosis, exhaustion, altered consciousness and low oxygen saturation; stabilize using ABCDE, provide care within scope and arrange urgent referral.","श्वासदर, सास फेर्न लाग्ने मेहनत, oxygen saturation र छातीको जाँच गर्नुहोस्। सामान्य रोगमा माथिल्लो श्वासप्रश्वास संक्रमण, निमोनिया, दम र COPD पर्छन्। अत्यधिक सास कष्ट, नीलोपन, थकान, चेतना परिवर्तन र oxygen कम हुनु खतरा संकेत हुन्; ABCDE अनुसार प्राथमिक मूल्याङ्कन गरी शीघ्र referral गर्नुहोस्।"],
 ["22. Cardiovascular diseases and red flags","Assess pulse, blood pressure, perfusion, edema and chest pain. Hypertension may be asymptomatic; confirm elevated readings using correct technique and repeat measurements. Suspected acute coronary syndrome, stroke, syncope with instability or shock requires emergency assessment and referral; do not delay for routine tests.","नाडी, रक्तचाप, रक्तप्रवाह, सुन्निने अवस्था र छाती दुखाइ मूल्याङ्कन गर्नुहोस्। उच्च रक्तचाप लक्षणविहीन पनि हुन सक्छ; सही तरिकाले नापेर पुनः पुष्टि गर्नुहोस्। हृदयाघातको शंका, stroke, अस्थिर अवस्थासहित बेहोस हुनु वा shock भए आकस्मिक मूल्याङ्कन र referral गर्नुहोस्।"],
 ["23. Gastrointestinal and liver disorders","Common presentations include diarrhea, vomiting, abdominal pain, dyspepsia, jaundice and gastrointestinal bleeding. Assess hydration, abdominal danger signs, stool history and medication use. Severe dehydration, persistent vomiting, blood in stool, rigid abdomen or jaundice with systemic illness needs urgent review.","पखाला, बान्ता, पेट दुखाइ, अपच, जन्डिस र पाचननलीबाट रक्तस्राव सामान्य समस्या हुन्। शरीरमा पानीको कमी, पेटका खतरा संकेत, दिसाको विवरण र औषधि प्रयोग जाँच्नुहोस्। गम्भीर dehydration, निरन्तर बान्ता, दिसामा रगत, कडा पेट वा बिरामी अवस्थासहित जन्डिस भए शीघ्र referral गर्नुहोस्।"],
 ["24. Renal and urinary disorders","Ask about urine volume, frequency, dysuria, hematuria, flank pain and edema. Urinary tract infection may cause dysuria and frequency; fever with flank pain may suggest upper urinary infection. Oliguria, anuria, severe dehydration, visible blood or suspected acute kidney injury requires prompt assessment.","पिसाबको मात्रा, पटक, पोल्ने, रगत, कम्मरको छेउ दुख्ने र सुन्निनेबारे सोध्नुहोस्। UTI मा पिसाब पोल्ने र पटक-पटक लाग्ने हुन सक्छ; ज्वरोसँग flank pain भए माथिल्लो urinary infection को शंका हुन्छ। पिसाब अत्यन्त कम/बन्द, देखिने रगत वा acute kidney injury को शंका भए शीघ्र जाँच आवश्यक हुन्छ।"],
 ["25. Neurological assessment and emergencies","Assess level of consciousness, pupils, speech, limb power, sensation, gait and seizures. Sudden facial droop, arm weakness or speech difficulty suggests stroke and is time-critical. A first seizure, prolonged seizure, repeated seizures without recovery, meningism or reduced consciousness needs emergency care.","चेतनाको स्तर, आँखाको pupil, बोली, हातखुट्टाको शक्ति, संवेदना, हिँडाइ र दौरा जाँच्नुहोस्। अचानक अनुहार बाङ्गिनु, हात कमजोर हुनु वा बोली बिग्रनु stroke का संकेत हुन सक्छन् र समय अत्यन्त महत्त्वपूर्ण हुन्छ। पहिलोपटक दौरा, लामो दौरा, होस नफर्की दोहोरिने दौरा वा चेतना घटे आकस्मिक सेवा चाहिन्छ।"],
 ["26. Common infectious diseases and infection control","Consider local epidemiology and exposure when assessing fever. Use standard precautions for every patient, hand hygiene, appropriate PPE, safe injection practices, respiratory hygiene and correct waste segregation. Suspected tuberculosis, measles, meningitis or other notifiable/high-risk infection requires appropriate precautions, notification and referral according to national guidance.","ज्वरो मूल्याङ्कन गर्दा स्थानीय रोगको अवस्था र exposure विचार गर्नुहोस्। सबै बिरामीमा हात सफाइ, उपयुक्त PPE, सुरक्षित injection, श्वासप्रश्वास शिष्टाचार र फोहोर छुट्याउने standard precaution अपनाउनुहोस्। क्षयरोग, दादुरा, meningitis वा उच्च जोखिम संक्रमणको शंका भए राष्ट्रिय निर्देशिकाअनुसार सावधानी, सूचना र referral गर्नुहोस्।"],
 ["27. Pediatric assessment and IMNCI danger signs","Assess feeding, activity, respiratory rate, chest indrawing, temperature, hydration and growth. General danger signs include inability to drink or breastfeed, vomiting everything, convulsions and lethargy or unconsciousness. Young infants need particular attention to poor feeding, fast or difficult breathing, fever or low temperature and reduced movement; refer urgently when danger signs are present.","खुवाइ, सक्रियता, श्वासदर, छाती भित्र तानिने, तापक्रम, hydration र वृद्धि जाँच्नुहोस्। सामान्य खतरा संकेतमा दूध/पानी पिउन नसक्नु, सबै कुरा बान्ता गर्नु, दौरा र सुस्त वा बेहोस हुनु पर्छन्। साना शिशुमा दूध नखानु, छिटो/गाह्रो सास, ज्वरो वा शरीर चिसो हुनु र कम चल्नु विशेष खतरा हुन्; संकेत देखिए शीघ्र referral गर्नुहोस्।"],
 ["28. Skin diseases and basic dermatology","Common conditions include scabies, fungal infections, eczema, impetigo and acne. Examine distribution, morphology, itch, pain, fever and contacts. Treat only within competence and local protocols; widespread infection, rapidly spreading redness, severe pain, mucosal involvement, systemic illness or suspected severe drug reaction requires urgent assessment.","खुजली, फंगल संक्रमण, eczema, impetigo र acne सामान्य छालाका समस्या हुन्। शरीरमा फैलावट, दागको प्रकार, चिलाउने/दुख्ने, ज्वरो र सम्पर्कमा आएका व्यक्तिबारे जाँच्नुहोस्। आफ्नो दक्षता र स्थानीय protocol भित्र मात्र उपचार गर्नुहोस्; फैलँदो रातोपन, धेरै दुखाइ, mucosa संलग्न वा गम्भीर औषधि प्रतिक्रिया भए शीघ्र जाँच आवश्यक हुन्छ।"],
 ["29. Mental health and psychosocial care","Use respectful, non-stigmatizing communication and assess mood, sleep, function, substance use and safety. Ask directly and calmly about self-harm thoughts when clinically indicated. Immediate risk of suicide, severe agitation, psychosis with danger, delirium or inability to care for basic needs requires urgent safety measures and referral.","सम्मानजनक र भेदभावरहित संवाद गर्नुहोस्; मनोदशा, निद्रा, दैनिक काम, पदार्थ प्रयोग र सुरक्षाबारे बुझ्नुहोस्। आवश्यक अवस्थामा आत्महानिको सोचबारे शान्त र स्पष्ट रूपमा सोध्नुहोस्। आत्महत्याको तत्काल जोखिम, खतरासहितको अत्यधिक उत्तेजना, psychosis, delirium वा आधारभूत हेरचाह गर्न नसक्ने अवस्था भए तत्काल सुरक्षा र referral आवश्यक हुन्छ।"],
 ["30. Obstetric and gynecological care","Antenatal assessment includes blood pressure, anemia symptoms, nutrition, danger signs and birth preparedness. Danger signs include vaginal bleeding, severe headache or visual symptoms, convulsions, severe abdominal pain, fever, leaking fluid or reduced fetal movement. Postpartum heavy bleeding, fever, severe headache or convulsions is an emergency.","गर्भावस्थाको जाँचमा रक्तचाप, रक्तअल्पताका लक्षण, पोषण, खतरा संकेत र प्रसूति तयारी समावेश गर्नुहोस्। योनीबाट रगत, कडा टाउको दुखाइ/दृष्टि समस्या, दौरा, कडा पेट दुखाइ, ज्वरो, पानी बग्नु वा बच्चा कम चल्नु खतरा संकेत हुन्। सुत्केरीपछि धेरै रक्तस्राव, ज्वरो, कडा टाउको दुखाइ वा दौरा आकस्मिक अवस्था हो।"],
 ["31. Wound care, fractures and surgical conditions","Assess wound location, contamination, depth, bleeding, distal circulation, sensation and movement. Control bleeding, cover wounds with clean dressings and assess tetanus immunization. Suspected open fracture, neurovascular compromise, compartment syndrome, major burns, abdominal rigidity or acute abdomen requires urgent referral; do not attempt procedures beyond scope.","घाउको स्थान, फोहोर, गहिराइ, रक्तस्राव, टाढाको रक्तसञ्चार, संवेदना र चाल जाँच्नुहोस्। रक्तस्राव नियन्त्रण गरी सफा dressing लगाउनुहोस् र tetanus खोप अवस्था जाँच्नुहोस्। खुला fracture, रक्तसञ्चार/नसामा समस्या, compartment syndrome, ठूलो burn वा acute abdomen भए शीघ्र referral गर्नुहोस्; आफ्नो कार्यक्षेत्रभन्दा बाहिरको प्रक्रिया नगर्नुहोस्।"],
 ["32. Eye, ENT and oral health essentials","Red flags include sudden visual loss, painful red eye, chemical eye exposure, ear discharge with mastoid swelling, airway compromise, severe sore throat with drooling and facial/oral swelling with fever. For chemical eye exposure, begin immediate copious irrigation and arrange urgent care. Refer suspected emergencies promptly.","अचानक दृष्टि हराउनु, दुख्ने रातो आँखा, आँखामा रसायन पर्नु, कानबाट पानीसँग mastoid सुन्निनु, श्वासमार्ग अवरुद्ध हुनु, र्‍याल चुहिने गरी घाँटी दुख्नु र ज्वरोसहित मुख/अनुहार सुन्निनु खतरा संकेत हुन्। आँखामा रसायन परे तुरुन्त प्रशस्त पानीले धुन सुरु गरी आकस्मिक उपचारमा पठाउनुहोस्।"]
 ];
 const Q=[
 ["The functional unit of the kidney is:","मिर्गौलाको कार्यात्मक एकाइ कुन हो?",["Nephron","Neuron","Alveolus","Hepatocyte"],0,"The nephron filters blood and contributes to urine formation.","Nephron ले रगत छानेर पिसाब बन्ने प्रक्रियामा काम गर्छ।","Anatomy & Physiology"],
 ["Which chamber pumps oxygenated blood into the systemic circulation?","शरीरभरि oxygenated blood पठाउने मुटुको कोठा कुन हो?",["Right atrium","Right ventricle","Left atrium","Left ventricle"],3,"The left ventricle pumps oxygenated blood into the aorta and systemic circulation.","Left ventricle ले aorta हुँदै शरीरभरि oxygenated blood पठाउँछ।","Anatomy & Physiology"],
 ["Insulin is secreted by which pancreatic cells?","Insulin pancreas का कुन कोषिकाले उत्पादन गर्छन्?",["Alpha cells","Beta cells","Acinar cells","Delta cells"],1,"Pancreatic beta cells secrete insulin; alpha cells secrete glucagon.","Pancreas का beta cells ले insulin र alpha cells ले glucagon उत्पादन गर्छन्।","Anatomy & Physiology"],
 ["Which sequence best describes a structured clinical history?","व्यवस्थित clinical history को राम्रो क्रम कुन हो?",["Presenting complaint, HPI, past history, medication/allergy, family/social history","Only diagnosis and prescription","Only vital signs","Only family history"],0,"A complete history explores the current problem and relevant medical, medication, allergy, family and social context.","पूर्ण इतिहासमा हालको समस्या र सम्बन्धित स्वास्थ्य, औषधि, एलर्जी, पारिवारिक तथा सामाजिक विवरण समेटिन्छ।","General Medicine"],
 ["Which is a core vital sign?","मुख्य vital sign कुन हो?",["Hair colour","Respiratory rate","Height only","Visual acuity"],1,"Temperature, pulse, respiratory rate and blood pressure are core vital signs.","तापक्रम, नाडी, श्वासदर र रक्तचाप मुख्य vital signs हुन्।","General Medicine"],
 ["A patient has severe breathlessness and cyanosis. What is the priority?","बिरामीलाई अत्यधिक सास कष्ट र नीलोपन छ। पहिलो प्राथमिकता के हो?",["Routine appointment next week","Urgent ABC assessment and emergency help","Give oral food","Ask them to walk"],1,"Severe respiratory distress and cyanosis are emergency signs requiring immediate assessment and help.","गम्भीर श्वास कष्ट र नीलोपन आकस्मिक संकेत हुन्; तुरुन्त मूल्याङ्कन र सहयोग चाहिन्छ।","General Medicine"],
 ["Persistent hyperglycemia is characteristic of:","लगातार hyperglycemia कुन रोगको विशेषता हो?",["Diabetes mellitus","Asthma","Scabies","Otitis externa"],0,"Diabetes mellitus involves persistent hyperglycemia due to impaired insulin secretion, action or both.","मधुमेहमा insulin उत्पादन वा कार्यमा समस्या भएर glucose बढ्छ।","General Medicine"],
 ["Which finding may suggest fluid overload?","कुन संकेतले शरीरमा तरल बढी भएको देखाउन सक्छ?",["Peripheral edema","Dry hair only","Improved appetite","Normal urine colour"],0,"Peripheral edema can occur with fluid retention and requires clinical context and assessment.","Peripheral edema तरल जम्मा हुँदा देखिन सक्छ; अन्य अवस्था पनि मूल्याङ्कन गर्नुपर्छ।","General Medicine"],
 ["Which is a neonatal danger sign?","नवजात शिशुको खतरा संकेत कुन हो?",["Feeding well","Convulsions","Normal activity","Regular feeding"],1,"Convulsions in a neonate are a danger sign requiring urgent assessment and referral.","नवजातमा दौरा गम्भीर खतरा संकेत हो र तत्काल referral चाहिन्छ।","General Medicine"],
 ["What is the first step in a systematic assessment of an acutely ill patient?","गम्भीर बिरामीको व्यवस्थित जाँचमा पहिलो चरण के हो?",["ABCDE approach","Routine discharge","Wait for laboratory report","Give an unverified medicine"],0,"ABCDE prioritizes life-threatening airway, breathing and circulation problems.","ABCDE ले airway, breathing र circulation का ज्यान जोखिमका समस्या प्राथमिकतामा राख्छ।","General Surgery"],
 ["Which symptom with pregnancy requires urgent referral?","गर्भावस्थामा कुन लक्षण भए तुरुन्त referral चाहिन्छ?",["Mild appetite change","Heavy vaginal bleeding","Occasional fetal movement","Mild fatigue after activity"],1,"Heavy vaginal bleeding is an obstetric danger sign.","धेरै योनी रक्तस्राव प्रसूति आकस्मिक संकेत हो।","General Surgery"],
 ["A thermal burn should initially be cooled with:","Thermal burn लाई सुरुमा के ले चिस्याउनु उपयुक्त हुन्छ?",["Cool running water","Ice directly","Toothpaste","Cooking oil"],0,"Cool running water is recommended; avoid ice and household substances.","चिसो बग्ने पानी प्रयोग गर्नुहोस्; बरफ वा घरेलु पदार्थ नलगाउनुहोस्।","General Surgery"],
 ["Which is an appropriate sharps safety practice?","धारिलो उपकरणको सुरक्षित अभ्यास कुन हो?",["Recap used needles with both hands","Dispose immediately into puncture-resistant sharps container","Leave on a tray","Bend used needles"],1,"Used sharps should be discarded immediately into an approved puncture-resistant container.","प्रयोग भएको धारिलो वस्तु तुरुन्त puncture-resistant sharps container मा फाल्नुपर्छ।","General Surgery"],
 ["Incidence refers to:","Incidence को अर्थ के हो?",["All existing cases","New cases occurring in a population at risk over time","Total hospital beds","Number of health workers"],1,"Incidence measures new cases over a specified period in a population at risk.","Incidence ले निश्चित अवधिमा जोखिममा रहेको जनसंख्याका नयाँ केस मापन गर्छ।","Community Health"],
 ["Prevalence includes:","Prevalence मा के समावेश हुन्छ?",["Only new cases","All existing cases at a specified time or period","Only deaths","Only exposed persons"],1,"Prevalence counts existing cases at a point or during a period.","Prevalence ले निश्चित समयमा वा अवधिमा रहेका सबै केस गन्छ।","Community Health"],
 ["A key principle of primary health care is:","प्राथमिक स्वास्थ्य सेवाको मुख्य सिद्धान्त कुन हो?",["Community participation","Only hospital-based care","No prevention","Care only for urban residents"],0,"Community participation is a core PHC principle.","समुदायको सहभागिता प्राथमिक स्वास्थ्य सेवाको मुख्य सिद्धान्त हो।","Community Health"],
 ["Which method makes drinking water safer at household level?","घरायसी तहमा पिउने पानी सुरक्षित बनाउने विधि कुन हो?",["Boiling appropriately","Adding soil","Storing uncovered","Mixing with wastewater"],0,"Appropriate boiling is an effective household water treatment method when done correctly.","सही तरिकाले उमाल्नु घरायसी पानी शुद्धीकरणको प्रभावकारी उपाय हो।","Community Health"],
 ["A balanced diet should provide:","सन्तुलित आहारले के उपलब्ध गराउनुपर्छ?",["Only carbohydrates","Adequate energy and essential nutrients in suitable proportions","Only vitamins","Only fats"],1,"A balanced diet provides adequate energy and essential nutrients in appropriate proportions.","सन्तुलित आहारले आवश्यक ऊर्जा र पोषक तत्व उचित अनुपातमा दिन्छ।","Community Health"],
 ["Which is an example of health promotion?","स्वास्थ्य प्रवर्द्धनको उदाहरण कुन हो?",["Community-led physical activity and nutrition programme","Ignoring local priorities","Providing information without engagement only","Discouraging participation"],0,"Health promotion supports people and communities to increase control over health.","स्वास्थ्य प्रवर्द्धनले व्यक्ति र समुदायलाई आफ्नो स्वास्थ्यमा नियन्त्रण बढाउन सहयोग गर्छ।","Community Health"],
 ["Cold chain is maintained to:","Cold chain किन कायम राखिन्छ?",["Preserve vaccine potency","Change vaccine colour","Freeze every medicine","Avoid recording temperature"],0,"Cold chain maintains recommended temperatures to preserve vaccine quality and potency.","खोपको गुणस्तर र प्रभावकारिता जोगाउन तोकिएको तापक्रम कायम गरिन्छ।","Community Health"],
 ["Which is the best approach to community diagnosis?","समुदाय निदानको राम्रो विधि कुन हो?",["Collect and analyze reliable data with community participation","Assume all communities are identical","Use rumours only","Exclude local leaders"],0,"Reliable data and community participation help identify priorities and feasible interventions.","भरपर्दो तथ्याङ्क र समुदाय सहभागिताले प्राथमिकता र व्यवहारिक उपाय पहिचान गर्छ।","Community Health"],
 ["A drug's pharmacokinetics describes:","Pharmacokinetics ले के वर्णन गर्छ?",["What the body does to the drug","Only drug price","Only tablet colour","What the drug does to the body"],0,"Pharmacokinetics includes absorption, distribution, metabolism and excretion.","Pharmacokinetics मा absorption, distribution, metabolism र excretion पर्छ।","Pharmacology"],
 ["Before giving a medicine, which should be checked?","औषधि दिनुअघि के जाँच्नुपर्छ?",["Allergy and current medicines","Only shoe size","Only occupation","Only preferred colour"],0,"Allergy, interactions, contraindications and patient factors are essential safety checks.","एलर्जी, interaction, contraindication र बिरामीको अवस्था जाँच्नु आवश्यक छ।","Pharmacology"],
 ["Antibiotics should be used:","Antibiotic कहिले प्रयोग गर्नुपर्छ?",["For every fever","When clinically indicated for susceptible bacterial infection","For all viral colds","To treat hypertension"],1,"Antibiotics are for indicated bacterial infections, not routine viral illnesses.","Antibiotic आवश्यक bacterial infection मा प्रयोग हुन्छ; सामान्य viral रोगमा होइन।","Pharmacology"],
 ["Which route places medicine directly into a vein?","औषधि सिधै नसामा दिने route कुन हो?",["Intravenous","Oral","Topical","Inhalational"],0,"Intravenous administration delivers medicine into a vein.","Intravenous route बाट औषधि नसामा दिइन्छ।","Pharmacology"],
 ["A prescription label should clearly include:","औषधिको label मा स्पष्ट रूपमा के हुनुपर्छ?",["Patient/drug directions and relevant dispensing details","Only decoration","Unverified abbreviations","No expiry information where required"],0,"Clear labeling supports correct use and patient safety; follow local legal requirements.","स्पष्ट label ले सही प्रयोग र बिरामी सुरक्षा बढाउँछ; स्थानीय कानुनी मापदण्ड पालना गर्नुपर्छ।","Pharmacology"],
 ["Shock is primarily a problem of:","Shock मुख्यतया कुन समस्यासँग सम्बन्धित छ?",["Inadequate tissue perfusion","Excessive hair growth","Improved circulation","Tooth discoloration"],0,"Shock is circulatory failure causing inadequate tissue perfusion.","Shock मा रक्तसञ्चार असफल भएर तन्तुमा पर्याप्त रक्तप्रवाह पुग्दैन।","General Surgery"],
 ["Which action is appropriate for external severe bleeding?","बाहिरी गम्भीर रक्तस्रावमा उपयुक्त कदम कुन हो?",["Apply firm direct pressure and call for urgent help","Wash and leave uncovered","Encourage walking","Apply soil"],0,"Firm direct pressure is a key first-aid measure while arranging emergency care.","आकस्मिक सहयोग मिलाउँदै घाउमा कडा प्रत्यक्ष दबाब दिनु प्राथमिक उपचारको मुख्य उपाय हो।","General Surgery"],
 ["Which is a warning sign of stroke?","Stroke को चेतावनी संकेत कुन हो?",["Sudden facial droop or one-sided weakness","Gradual nail growth","Mild thirst after exercise","Itchy scalp only"],0,"Sudden facial weakness, arm weakness or speech difficulty requires emergency response.","अचानक अनुहार बाङ्गिनु, हात कमजोर हुनु वा बोली बिग्रनु आकस्मिक संकेत हुन्।","General Surgery"],
 ["Which is a common sign of anemia?","रक्तअल्पताको सामान्य संकेत कुन हो?",["Pallor and fatigue","Blue sclera in all cases","Increased hair length","Excessive sweating only"],0,"Anemia may cause pallor, fatigue, breathlessness and reduced exercise tolerance.","रक्तअल्पतामा फिक्कापन, थकान, सास कष्ट र काम गर्ने क्षमता घट्न सक्छ।","Clinical Pathology"],
 ["Which sample is commonly used for a complete blood count?","Complete blood count का लागि सामान्यतया कुन नमुना प्रयोग हुन्छ?",["EDTA anticoagulated blood","Urine only","Saliva only","Unpreserved stool"],0,"CBC is commonly performed on EDTA-anticoagulated whole blood.","CBC का लागि EDTA भएको anticoagulated whole blood सामान्यतया प्रयोग हुन्छ।","Clinical Pathology"],
 ["Sterilization means:","Sterilization को अर्थ के हो?",["Destruction/removal of all forms of microbial life including spores","Removal of visible dirt only","Reduction of odour","Rinsing with water"],0,"Sterilization destroys or removes all forms of microbial life, including bacterial spores.","Sterilization ले bacterial spores सहित सबै प्रकारका सूक्ष्मजीव नष्ट वा हटाउँछ।","Clinical Pathology"],
 ["Which organism causes malaria?","मलेरिया कुन जीवका कारण हुन्छ?",["Plasmodium species","Candida species","Staphylococcus aureus","Entamoeba coli"],0,"Malaria is caused by Plasmodium parasites transmitted by infected female Anopheles mosquitoes.","मलेरिया Plasmodium परजीवीबाट हुन्छ, जुन संक्रमित पोथी Anopheles लामखुट्टेले सार्छ।","Clinical Pathology"],

  ["Which bone protects the brain?","मस्तिष्कलाई कुन हड्डीले सुरक्षा गर्छ?",["Skull","Femur","Patella","Tibia"],0,"The skull encloses and protects the brain.","Skull ले मस्तिष्कलाई घेरेर सुरक्षा गर्छ।","Anatomy & Physiology"],
  ["Which blood cells mainly carry oxygen?","अक्सिजन बोक्ने मुख्य रक्तकोष कुन हो?",["White blood cells","Red blood cells","Platelets","Plasma cells"],1,"Red blood cells contain hemoglobin, which carries oxygen.","रातो रक्तकोषमा hemoglobin हुन्छ, जसले अक्सिजन बोक्छ।","Anatomy & Physiology"],
  ["Which part of the brain helps coordinate balance and movement?","सन्तुलन र चाल समन्वय गर्न मस्तिष्कको कुन भागले मद्दत गर्छ?",["Cerebellum","Medulla","Hypothalamus","Cerebrum"],0,"The cerebellum coordinates movement, posture and balance.","Cerebellum ले चाल, शरीरको अवस्था र सन्तुलन समन्वय गर्छ।","Anatomy & Physiology"],
  ["The main site of gas exchange in the lungs is:","फोक्सोमा ग्यास आदानप्रदान हुने मुख्य स्थान कुन हो?",["Trachea","Bronchi","Alveoli","Pleura"],2,"Alveoli provide a large thin surface for oxygen and carbon dioxide exchange.","Alveoli को पातलो सतहमा अक्सिजन र कार्बन डाइअक्साइड साटासाट हुन्छ।","Anatomy & Physiology"],
  ["Which hormone lowers blood glucose?","रगतको glucose घटाउने hormone कुन हो?",["Glucagon","Insulin","Adrenaline","Cortisol"],1,"Insulin promotes glucose uptake and storage, lowering blood glucose.","Insulin ले glucose को उपयोग र भण्डारण बढाएर रगतको glucose घटाउँछ।","Anatomy & Physiology"],
  ["The best first step when planning a community health programme is to:","समुदाय स्वास्थ्य कार्यक्रम योजना बनाउँदा पहिलो उपयुक्त कदम के हो?",["Assess community needs and resources","Purchase equipment immediately","Start without baseline data","Select activities without consultation"],0,"A needs assessment identifies priority problems, resources and community expectations.","आवश्यकता मूल्याङ्कनले प्राथमिक समस्या, स्रोत र समुदायको अपेक्षा पहिचान गर्छ।","Community Health"],
  ["Which indicator commonly measures infant deaths among live births?","जीवित जन्ममध्ये शिशु मृत्यु मापन गर्ने सूचक कुन हो?",["Maternal mortality ratio","Infant mortality rate","Crude birth rate","General fertility rate"],1,"Infant mortality rate measures deaths under one year per 1,000 live births in a specified period.","शिशु मृत्यु दरले निश्चित अवधिमा प्रति १,००० जीवित जन्ममा एक वर्षमुनिका मृत्यु मापन गर्छ।","Community Health"],
  ["Which is a primary prevention activity?","प्राथमिक रोकथामको उदाहरण कुन हो?",["Rehabilitation after stroke","Immunization","Screening for cervical cancer","Physiotherapy after fracture"],1,"Immunization prevents disease before it occurs.","खोपले रोग हुनुअघि नै रोकथाम गर्छ।","Community Health"],
  ["A disease constantly present in a particular area is described as:","कुनै क्षेत्रमा निरन्तर देखिने रोगलाई के भनिन्छ?",["Epidemic","Pandemic","Endemic","Sporadic outbreak"],2,"Endemic disease maintains a usual presence in a defined population or area.","Endemic रोग निश्चित समुदाय वा क्षेत्रमा सामान्य रूपमा निरन्तर रहन्छ।","Community Health"],
  ["Which measure is most useful for preventing fecal-oral disease transmission?","दिसा–मुख मार्गबाट सर्ने रोग रोक्न कुन उपाय उपयोगी हुन्छ?",["Handwashing with soap after toilet use","Sharing drinking cups","Open defecation","Storing food uncovered"],0,"Handwashing with soap interrupts transmission of fecal pathogens.","साबुनपानीले हात धुँदा दिसाबाट सर्ने जीवाणुको प्रसार रोकिन्छ।","Community Health"],
  ["Which vitamin deficiency causes night blindness?","कुन vitamin को कमीले राति कम देख्ने समस्या हुन्छ?",["Vitamin C","Vitamin D","Vitamin A","Vitamin K"],2,"Vitamin A is essential for retinal function; deficiency can cause night blindness.","Vitamin A आँखाको retina को कामका लागि आवश्यक हुन्छ; कमीले राति कम देखिन्छ।","Community Health"],
  ["A family planning method that also reduces STI transmission risk is:","STI सर्ने जोखिम पनि घटाउने परिवार नियोजन विधि कुन हो?",["Condom","Copper IUD","Oral pill","Implant"],0,"Correct and consistent condom use reduces risk of many STIs and pregnancy.","सही र नियमित condom प्रयोगले धेरै STI र गर्भधारणको जोखिम घटाउँछ।","Community Health"],
  ["Which is an example of a social determinant of health?","स्वास्थ्यको सामाजिक निर्धारकको उदाहरण कुन हो?",["Housing and education","Blood group only","Eye colour","Height alone"],0,"Housing, education, income and employment influence health opportunities and outcomes.","आवास, शिक्षा, आय र रोजगारीले स्वास्थ्य अवसर र नतिजामा प्रभाव पार्छन्।","Community Health"],
  ["The purpose of disease surveillance is to:","रोग निगरानीको मुख्य उद्देश्य के हो?",["Collect, analyze and use health data for action","Replace all clinical diagnosis","Record only hospital income","Avoid reporting outbreaks"],0,"Surveillance supports early detection, trend monitoring and public health response.","निगरानीले रोग चाँडो पहिचान, प्रवृत्ति अनुगमन र जनस्वास्थ्य प्रतिक्रिया सम्भव बनाउँछ।","Community Health"],
  ["Which waste should be placed in a puncture-resistant sharps container?","छेड्न नसकिने sharps container मा कुन फोहोर राख्नुपर्छ?",["Used needles","Food wrappers","Paper towels","Clean packaging"],0,"Used needles and other sharps must go directly into approved puncture-resistant containers.","प्रयोग भएका सुई र धारिला वस्तु तुरुन्त स्वीकृत puncture-resistant container मा राख्नुपर्छ।","Community Health"],
  ["Exclusive breastfeeding is generally recommended for the first:","पूर्ण स्तनपान सामान्यतया सुरुका कति महिनासम्म सिफारिस गरिन्छ?",["2 months","4 months","6 months","12 months"],2,"WHO recommends exclusive breastfeeding for the first six months, with complementary foods thereafter.","WHO ले सुरुका ६ महिना पूर्ण स्तनपान र त्यसपछि पूरक आहार सिफारिस गर्छ।","Community Health"],
  ["Which study design follows exposed and unexposed groups over time?","Exposure भएका र नभएका समूहलाई समयसँगै पछ्याउने अध्ययन कुन हो?",["Cohort study","Case report","Cross-sectional study","Case series"],0,"A cohort study follows groups to compare outcome occurrence over time.","Cohort अध्ययनले समयसँगै समूहहरूमा नतिजा तुलना गर्छ।","Community Health"],
  ["The most appropriate measure during a suspected foodborne outbreak is to:","खाद्यजन्य रोगको प्रकोप शंका हुँदा उपयुक्त कदम के हो?",["Notify public health authority and investigate promptly","Wait until all patients recover","Destroy all records","Give antibiotics to everyone without assessment"],0,"Prompt notification, case finding and source investigation help control outbreaks.","तुरुन्त सूचना, केस खोजी र स्रोत अनुसन्धानले प्रकोप नियन्त्रणमा मद्दत गर्छ।","Community Health"],
  ["Which symptom is a common feature of hypoglycemia?","Hypoglycemia को सामान्य लक्षण कुन हो?",["Sweating and tremor","Slow nail growth","Jaundice","Persistent ankle deformity"],0,"Low blood glucose may cause sweating, tremor, hunger, confusion or seizures.","रगतमा glucose घट्दा पसिना, हात काम्ने, भोक, अन्योल वा दौरा हुन सक्छ।","General Medicine"],
  ["Which finding suggests dehydration in a child?","बालबालिकामा dehydration को संकेत कुन हो?",["Sunken eyes and reduced urine","Excessive tears","Frequent urination with moist mouth","Rapid weight gain"],0,"Sunken eyes, thirst, poor drinking and reduced urine can indicate dehydration; assess using current IMNCI guidance.","आँखा गाडिनु, तिर्खा, कम पिउनु र पिसाब कम हुनु dehydration का संकेत हुन सक्छन्; IMNCI अनुसार मूल्याङ्कन गर्नुहोस्।","General Medicine"],
  ["Which condition commonly causes wheezing due to reversible airway narrowing?","श्वासनली साँघुरिँदा wheezing हुने सामान्य रोग कुन हो?",["Asthma","Appendicitis","Nephritis","Osteoarthritis"],0,"Asthma involves variable airway inflammation and narrowing, often causing wheeze and breathlessness.","Asthma मा श्वासनलीमा सूजन र साँघुरोपन बदलिँदै जान्छ, जसले wheeze र सास कष्ट गराउँछ।","General Medicine"],
  ["A classic symptom of pulmonary tuberculosis is:","फोक्सोको क्षयरोगको सामान्य लक्षण कुन हो?",["Persistent cough, sometimes with blood","Sudden toothache only","Ear discharge only","Acute ankle swelling"],0,"Pulmonary TB may cause prolonged cough, fever, night sweats, weight loss and sometimes hemoptysis.","फोक्सोको TB मा लामो खोकी, ज्वरो, राति पसिना, तौल घट्नु र कहिलेकाहीँ खकारमा रगत आउन सक्छ।","General Medicine"],
  ["Which symptom is most concerning for meningitis?","Meningitis को शंकामा कुन लक्षण बढी चिन्ताजनक हुन्छ?",["Fever with neck stiffness and altered consciousness","Mild seasonal sneezing","Isolated callus","Hair loss"],0,"Fever, neck stiffness, severe headache and altered mental status require urgent assessment.","ज्वरो, घाँटी कडापन, कडा टाउको दुखाइ र चेतना परिवर्तनमा तुरुन्त जाँच आवश्यक हुन्छ।","General Medicine"],
  ["Which is a common feature of hypothyroidism?","Hypothyroidism को सामान्य विशेषता कुन हो?",["Cold intolerance and fatigue","Heat intolerance and tremor only","Excessive thirst only","Sudden hearing loss"],0,"Reduced thyroid hormone may cause fatigue, cold intolerance, constipation and weight gain.","Thyroid hormone कम हुँदा थकान, चिसो सहन नसक्नु, कब्जियत र तौल बढ्न सक्छ।","General Medicine"],
  ["Which finding may indicate severe pneumonia in a young child?","सानो बालबालिकामा गम्भीर pneumonia को संकेत कुन हुन सक्छ?",["Chest indrawing or danger signs","Normal feeding and play","Mild isolated rash","Normal breathing"],0,"Chest indrawing, hypoxemia or general danger signs need urgent assessment and referral according to IMNCI.","छाती भित्र तानिनु, hypoxemia वा सामान्य खतरा संकेत भए IMNCI अनुसार तुरुन्त जाँच र referral चाहिन्छ।","General Medicine"],
  ["Which condition is characterized by inflammation of the liver?","कलेजोमा सूजन हुने अवस्थालाई के भनिन्छ?",["Hepatitis","Gastritis","Nephrosis","Arthritis"],0,"Hepatitis means inflammation of the liver and may be caused by viruses, toxins or other conditions.","Hepatitis भनेको कलेजोको सूजन हो; virus, विषाक्त पदार्थ वा अन्य कारण हुन सक्छ।","General Medicine"],
  ["A patient with sudden facial droop, arm weakness and speech difficulty may be having:","अचानक अनुहार बाङ्गिनु, हात कमजोर हुनु र बोली बिग्रनु कुन अवस्थाको संकेत हुन सक्छ?",["Stroke","Otitis externa","Gastritis","Conjunctivitis"],0,"Use a stroke recognition pathway and activate emergency referral immediately; time matters.","Stroke शंका भए तत्काल emergency referral सक्रिय गर्नुहोस्; समय अत्यन्त महत्त्वपूर्ण हुन्छ।","General Medicine"],
  ["Which is an appropriate approach to a patient with depression?","Depression भएका बिरामीसँग उपयुक्त व्यवहार कुन हो?",["Listen without judgment and assess safety, including self-harm risk","Dismiss symptoms as laziness","Promise a guaranteed cure","Stop all prescribed medicines abruptly"],0,"Respectful listening and safety assessment are important; urgent risk requires immediate support and referral.","सम्मानपूर्वक सुन्नु र सुरक्षाको मूल्याङ्कन महत्त्वपूर्ण हुन्छ; तत्काल जोखिम भए तुरुन्त सहयोग र referral चाहिन्छ।","General Medicine"],
  ["Which skin condition is commonly associated with intense itching at night and burrows?","राति धेरै चिलाउने र छालामा साना सुरुङजस्ता दाग हुने रोग कुन हो?",["Scabies","Vitiligo","Acne vulgaris","Alopecia"],0,"Scabies is caused by mites and often causes intense nocturnal itching and burrows.","Scabies mite का कारण हुन्छ र राति धेरै चिलाउने तथा burrow देखिन सक्छ।","General Medicine"],
  ["Which finding is typical of iron-deficiency anemia?","Iron deficiency anemia मा सामान्यतया के देखिन्छ?",["Low hemoglobin with microcytic hypochromic red cells","High hemoglobin with macrocytosis","High platelet count in every case","Normal iron stores"],0,"Iron deficiency commonly produces microcytic, hypochromic anemia; confirm with appropriate tests.","Iron कमीले प्रायः microcytic, hypochromic anemia गराउँछ; उपयुक्त परीक्षणबाट पुष्टि गर्नुपर्छ।","General Medicine"],
  ["Which medicine class is commonly used as a reliever in acute asthma under a treatment plan?","उपचार योजनाअनुसार acute asthma मा छिटो राहतका लागि कुन औषधि समूह प्रयोग हुन्छ?",["Short-acting bronchodilator","Antacid","Antifungal","Anticoagulant"],0,"A short-acting inhaled bronchodilator may be used for rapid relief according to the patient's prescribed plan and current guidelines.","बिरामीको prescribed plan र हालको guideline अनुसार short-acting inhaled bronchodilator छिटो राहतका लागि प्रयोग हुन सक्छ।","Pharmacology"],
  ["Paracetamol is primarily used as:","Paracetamol मुख्यतया केका लागि प्रयोग हुन्छ?",["Analgesic and antipyretic","Antibiotic","Anticoagulant","Antifungal"],0,"Paracetamol relieves pain and reduces fever; dose limits and liver risks must be considered.","Paracetamol ले दुखाइ र ज्वरो घटाउँछ; मात्रा सीमा र कलेजोसम्बन्धी जोखिम विचार गर्नुपर्छ।","Pharmacology"],
  ["Which route generally has the fastest systemic effect in an emergency when appropriately indicated?","आवश्यक अवस्थामा आकस्मिक उपचारमा कुन route ले सामान्यतया छिटो systemic प्रभाव दिन्छ?",["Intravenous","Oral","Topical","Rectal"],0,"Intravenous administration delivers medicine directly into circulation and can act rapidly; it requires trained staff and monitoring.","Intravenous बाट औषधि सिधै रक्तसञ्चारमा पुग्छ र छिटो काम गर्न सक्छ; तालिमप्राप्त कर्मचारी र निगरानी चाहिन्छ।","Pharmacology"],
  ["A contraindication is:","Contraindication भनेको के हो?",["A reason a medicine or procedure should not be used","The brand name of a drug","The price of a medicine","A routine follow-up date"],0,"A contraindication is a condition or factor that makes a treatment inadvisable or unsafe.","कुनै अवस्था वा कारणले उपचार अनुपयुक्त वा असुरक्षित बनाउँछ भने त्यसलाई contraindication भनिन्छ।","Pharmacology"],
  ["Which information is essential when calculating a medicine dose for a child?","बालबालिकाको औषधि मात्रा गणना गर्दा कुन जानकारी आवश्यक हुन्छ?",["Accurate current weight and prescribed dosing guidance","Hair colour","School grade","Shoe size"],0,"Many pediatric doses are weight-based; verify weight, concentration, maximum dose and local protocol.","धेरै बाल औषधिको मात्रा तौलअनुसार हुन्छ; तौल, concentration, अधिकतम मात्रा र स्थानीय protocol जाँच्नुहोस्।","Pharmacology"],
  ["What is the first priority when an unconscious patient is found?","बेहोस बिरामी भेटिँदा पहिलो प्राथमिकता के हो?",["Check responsiveness and call for help; assess airway and breathing","Give oral water","Make the patient stand","Leave the patient alone"],0,"Check response, summon emergency help and assess airway and normal breathing; follow BLS protocol.","प्रतिक्रिया जाँच्नुहोस्, आकस्मिक सहयोग बोलाउनुहोस् र airway तथा सामान्य श्वास जाँचेर BLS protocol पालना गर्नुहोस्।","General Surgery"],
  ["Which position is generally appropriate for a conscious patient with suspected shock while awaiting help, if no injury or breathing issue prevents it?","चेतन अवस्थामा shock शंका भएको र सहयोग पर्खिरहेको बिरामीलाई चोट वा श्वास समस्याले रोक्दैन भने सामान्यतया कुन अवस्था उपयुक्त हुन्छ?",["Lie flat and keep warm","Make the patient walk","Give a large meal","Sit in a hot bath"],0,"Keep the patient lying comfortably and warm; manage the cause and follow emergency protocol. Avoid unnecessary movement.","बिरामीलाई आरामदायी रूपमा सुताएर न्यानो राख्नुहोस्; कारणको व्यवस्थापन र आकस्मिक protocol पालना गर्नुहोस्। अनावश्यक हिँडडुल नगराउनुहोस्।","General Surgery"],
  ["Which action is important after a needle-stick injury?","सुईले घोचेपछि कुन कदम महत्त्वपूर्ण हुन्छ?",["Wash the area promptly and report immediately for risk assessment","Squeeze aggressively and hide the incident","Apply bleach","Wait several weeks before reporting"],0,"Wash with soap and water, report promptly and obtain occupational exposure assessment and indicated PEP without delay.","साबुनपानीले सफा गरी तुरुन्त रिपोर्ट गर्नुहोस् र occupational exposure मूल्याङ्कन तथा आवश्यक PEP ढिलाइ नगरी लिनुहोस्।","General Surgery"],
  ["Which symptom may indicate ectopic pregnancy rupture?","Ectopic pregnancy फुटेको संकेत कुन हुन सक्छ?",["Severe abdominal pain with dizziness or collapse","Mild hunger","Itchy scalp","Chronic mild backache only"],0,"Severe pain, vaginal bleeding, dizziness or collapse in possible pregnancy is an emergency.","गर्भावस्थाको सम्भावनासँगै कडा पेट दुखाइ, रक्तस्राव, चक्कर वा collapse आकस्मिक अवस्था हो।","General Surgery"],
  ["The third stage of labour is the period from birth of the baby until:","प्रसवको तेस्रो चरण बच्चा जन्मेदेखि के निस्किएसम्मको अवधि हो?",["Delivery of the placenta","Onset of contractions","Full cervical dilatation","First antenatal visit"],0,"The third stage ends with delivery of the placenta and membranes.","तेस्रो चरण placenta र membranes निस्किएपछि समाप्त हुन्छ।","General Surgery"],
  ["Which is a common sign of acute appendicitis?","Acute appendicitis को सामान्य संकेत कुन हो?",["Pain that may migrate to the right lower abdomen","Painless jaundice only","Bilateral ear pain","Chronic itchy eyes"],0,"Appendicitis often begins with central abdominal pain that migrates to the right lower quadrant, with nausea or fever.","Appendicitis मा सुरुमा पेटको बीच दुखेर दायाँ तल्लो भागमा सर्न सक्छ; वाकवाकी वा ज्वरो हुन सक्छ।","General Surgery"],
  ["A foreign body in the eye should generally be managed by:","आँखामा बाहिरी वस्तु परेमा सामान्यतया के गर्नुपर्छ?",["Avoid rubbing and arrange assessment; irrigate loose particles if appropriate","Rub the eye firmly","Use sharp instruments to remove it","Apply household chemicals"],0,"Do not rub or attempt removal of embedded objects; irrigate loose superficial particles when safe and refer for assessment.","आँखा नमिच्नुहोस् र गाडिएको वस्तु आफैँ ननिकाल्नुहोस्; सुरक्षित भए सतही कण पानीले पखालेर जाँचका लागि पठाउनुहोस्।","General Surgery"],
  ["Which condition commonly causes ear pain with a bulging tympanic membrane?","कान दुखाइसँग tympanic membrane फुलेको देखिने सामान्य अवस्था कुन हो?",["Acute otitis media","Cataract","Sinus bradycardia","Dermatitis"],0,"Acute otitis media can cause otalgia, fever and a bulging inflamed tympanic membrane.","Acute otitis media मा कान दुख्ने, ज्वरो र tympanic membrane फुलेको देखिन सक्छ।","General Surgery"],
  ["Which is the safest initial action for a suspected fracture?","हड्डी भाँचिएको शंका हुँदा सुरक्षित प्रारम्भिक कदम कुन हो?",["Immobilize in the position found and assess circulation","Force the limb straight","Massage the injured area","Ask the patient to test weight-bearing repeatedly"],0,"Support and immobilize the injured part, check distal circulation and arrange appropriate care.","घाइते भागलाई भेटिएको अवस्थामै सहारा दिएर स्थिर राख्नुहोस्, टाढाको रक्तसञ्चार जाँच्नुहोस् र उपचार मिलाउनुहोस्।","General Surgery"],
  ["Which blood component is mainly responsible for clot formation?","रगत जमाउन मुख्य भूमिका खेल्ने रक्तघटक कुन हो?",["Platelets","Red blood cells","Albumin","Neutrophils"],0,"Platelets adhere and aggregate to form the initial platelet plug in hemostasis.","Platelets टाँसिएर र एकत्रित भएर hemostasis को प्रारम्भिक plug बनाउँछन्।","Clinical Pathology"],
  ["Which test is commonly used to assess average blood glucose over about 2–3 months?","करिब २–३ महिनाको औसत blood glucose मूल्याङ्कन गर्न कुन परीक्षण प्रयोग हुन्छ?",["HbA1c","Bleeding time","Serum bilirubin","Urine microscopy"],0,"HbA1c reflects average glycemia over the preceding weeks to months, commonly about three months.","HbA1c ले पछिल्ला हप्ता/महिनाको औसत glucose देखाउँछ, सामान्यतया करिब तीन महिना।","Clinical Pathology"],

  ["Which structure carries urine from the kidney to the bladder?","मिर्गौलाबाट पिसाब bladder सम्म लैजाने संरचना कुन हो?",["Ureter","Urethra","Renal artery","Nephron"],0,"The ureter transports urine from each kidney to the urinary bladder.","Ureter ले प्रत्येक मिर्गौलाबाट पिसाब urinary bladder सम्म पुर्‍याउँछ।","Anatomy & Physiology"],
  ["Which condition is a common cause of acute watery diarrhea in children?","बालबालिकामा acute watery diarrhea को सामान्य कारण कुन हो?",["Infectious gastroenteritis","Cataract","Osteoporosis","Otitis externa"],0,"Acute gastroenteritis is a common cause; assess dehydration and follow current child-health protocols.","Acute gastroenteritis सामान्य कारण हो; dehydration जाँचेर बालस्वास्थ्य protocol पालना गर्नुहोस्।","General Medicine"],
  ["Which route is preferred for oral rehydration solution in a child who can drink?","पिउन सक्ने बालबालिकालाई ORS दिने उपयुक्त route कुन हो?",["Oral, in frequent small amounts","Intramuscular","Intravenous in every case","Topical"],0,"Give ORS orally in frequent small sips; severe dehydration or inability to drink needs urgent protocol-based care.","ORS मुखबाट थोरै-थोरै गरी पटकपटक दिनुहोस्; गम्भीर dehydration वा पिउन नसक्ने अवस्थामा protocol अनुसार तत्काल उपचार चाहिन्छ।","General Medicine"],
  ["Which laboratory finding is most consistent with bacterial infection in many acute cases?","धेरै acute अवस्थामा bacterial infection सँग मिल्ने laboratory finding कुन हो?",["Neutrophil predominance","Low platelet count in every case","Absent red blood cells","High urine glucose only"],0,"Neutrophilia can support bacterial infection but must be interpreted with clinical findings and other tests.","Neutrophil बढ्नु bacterial infection सँग मिल्न सक्छ, तर clinical अवस्था र अन्य परीक्षणसँगै व्याख्या गर्नुपर्छ।","Clinical Pathology"],
 ];
 const state={mode:"",index:0,answers:{},timer:null,left:0,items:[]};
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 function panel(html){root.querySelector("#haContent").innerHTML=html;root.querySelector("#haContent").scrollIntoView({behavior:"smooth",block:"start"});}
 function menu(){
  panel('<div class="ha-overview"><div class="ha-kpis"><div><b>'+notes.length+'</b><small>विस्तृत Notes</small></div><div><b>'+Q.length+'</b><small>अहिलेका MCQ</small></div><div><b>500+</b><small>लक्ष्य MCQ</small></div></div><p>MCQ बैंक चरणबद्ध रूपमा बढाइँदैछ। अहिलेको प्रश्न बैंक प्रारम्भिक संस्करण हो; ५००+ अद्वितीय र समीक्षा गरिएका प्रश्न पूरा नभएसम्म संख्या लक्ष्य मात्र हो।</p></div><div class="ha-actions"><button data-ha="notes">📚 Detailed Notes</button><button data-ha="practice">🧠 MCQ Practice</button><button data-ha="timed">⏱️ Timed Practice</button><button data-ha="mock">📝 Full Syllabus Mock</button></div><h3>NHPC Licensing Syllabus – Subject Weightage</h3><div class="ha-topic-list">'+topics.map(t=>'<article><div><b>'+t[0]+'</b><strong>'+t[1]+'</strong></div><p>'+t[2]+'</p><p class="np">'+t[3]+'</p></article>').join("")+'</div><div class="notice"><b>परीक्षा ढाँचाबारे स्पष्टता</b><p>NHPC को उपलब्ध HA licensing syllabus ले विषयगत भार १०%, २५%, २५%, १०%, २५%, ५% तोकेको छ। यसले MCQ संख्या, कुल परीक्षा समय वा negative marking निर्दिष्ट गरेको छैन। त्यसैले यहाँका timed practice र mock समय अभ्यासका लागि राखिएका हुन्, आधिकारिक परीक्षा समय होइनन्।</p></div>');
 }
 function showNotes(){panel('<h3>विस्तृत अध्ययन Notes</h3><p class="muted">English concept + नेपाली व्याख्या • Clinical safety focus</p>'+notes.map(n=>'<article class="ha-note"><h4>'+n[0]+'</h4><p>'+n[1]+'</p><p class="np">'+n[2]+'</p></article>').join("")+'<button data-ha="menu" class="smallbtn">← मुख्य मेनु</button>');}
 function start(mode){
  clearInterval(state.timer);state.mode=mode;state.index=0;state.answers={};
  const size=mode==="timed"?10:Q.length;state.items=Q.slice(0,size);state.left=mode==="timed"?600:1800;
  renderQuestion();state.timer=setInterval(()=>{state.left--;const el=root.querySelector("#haTimer");if(el)el.textContent=fmt(state.left);if(state.left<=0)finish();},1000);
 }
 function fmt(n){return Math.floor(n/60).toString().padStart(2,"0")+":"+Math.max(0,n%60).toString().padStart(2,"0")}
 function renderQuestion(){
  const q=state.items[state.index],selected=state.answers[state.index];
  panel('<div class="ha-test-head"><span>'+(state.mode==="timed"?"TIMED PRACTICE":"FULL SYLLABUS PRACTICE MOCK")+'</span><b id="haTimer">'+fmt(state.left)+'</b></div><div class="ha-progress"><span style="width:'+((state.index+1)/state.items.length*100)+'%"></span></div><p class="muted">प्रश्न '+(state.index+1)+' / '+state.items.length+' • प्रत्येक १ अंक • जम्मा '+state.items.length+' अंक</p><article class="ha-question"><small>'+q[6]+'</small><h3>'+q[0]+'</h3><p class="np">'+q[1]+'</p><div class="ha-options">'+q[2].map((o,i)=>'<button class="'+(selected===i?"selected":"")+'" data-ha-option="'+i+'">'+String.fromCharCode(65+i)+'. '+o+'</button>').join("")+'</div></article><div class="ha-nav"><button data-ha-prev '+(state.index===0?"disabled":"")+'>← अघिल्लो</button><button data-ha-next>'+(state.index===state.items.length-1?"Submit Test":"अर्को →")+'</button></div>');
 }
 function finish(){
  clearInterval(state.timer);let score=0;const details=state.items.map((q,i)=>{const ok=state.answers[i]===q[3];if(ok)score++;return {q,selected:state.answers[i],ok}});
  if(window.DHPNProgress)window.DHPNProgress.recordMock("NHPC HA – General Medicine",score,state.items.length);
  const pct=Math.round(score/state.items.length*100);
  panel('<div class="ha-result"><h3>परीक्षा नतिजा</h3><div class="ha-score">'+score+' / '+state.items.length+'</div><b>'+pct+'% सही</b><p>यो अभ्यास नतिजा हो, NHPC को आधिकारिक pass mark होइन।</p><p>सही: '+score+' • गलत/छुटेका: '+(state.items.length-score)+'</p></div><h3>उत्तर समीक्षा</h3>'+details.map((d,i)=>'<article class="ha-review"><b>'+(i+1)+'. '+d.q[0]+'</b><p class="np">'+d.q[1]+'</p><p class="'+(d.ok?"correct":"incorrect")+'">'+(d.ok?"सही उत्तर":"गलत वा उत्तर नदिएको")+' • '+d.q[2][d.q[3]]+'</p><p>'+d.q[4]+'</p><p class="np">'+d.q[5]+'</p></article>').join("")+'<button data-ha="menu" class="smallbtn">मुख्य मेनुमा फर्कनुहोस्</button>');
 }
 function practice(){
  state.mode="practice";state.items=Q;state.index=0;state.answers={};renderPracticeQ();
 }
 function renderPracticeQ(){
  const q=Q[state.index],selected=state.answers[state.index],done=selected!==undefined;
  panel('<p class="muted">MCQ '+(state.index+1)+' / '+Q.length+' • '+q[6]+'</p><article class="ha-question"><h3>'+q[0]+'</h3><p class="np">'+q[1]+'</p><div class="ha-options">'+q[2].map((o,i)=>'<button class="'+(selected===i?"selected":"")+'" data-ha-option="'+i+'">'+String.fromCharCode(65+i)+'. '+o+'</button>').join("")+'</div>'+(done?'<div class="ha-explain"><b>'+(selected===q[3]?"सही उत्तर!":"सही उत्तर: "+q[2][q[3]])+'</b><p>'+q[4]+'</p><p class="np">'+q[5]+'</p></div>':"")+'</article><div class="ha-nav"><button data-ha-practice-prev '+(state.index===0?"disabled":"")+'>← अघिल्लो</button><button data-ha-practice-next>'+(state.index===Q.length-1?"समाप्त":"अर्को →")+'</button></div><button data-ha="menu" class="smallbtn">मुख्य मेनु</button>');
 }
 root.addEventListener("click",e=>{
  const b=e.target.closest("button");if(!b)return;
  if(b.dataset.ha){const a=b.dataset.ha;if(a==="menu")menu();if(a==="notes")showNotes();if(a==="practice")practice();if(a==="timed")start("timed");if(a==="mock")start("mock");return;}
  if(b.dataset.haOption!==undefined){const idx=Number(b.dataset.haOption);if(state.mode==="practice"){state.answers[state.index]=idx;renderPracticeQ();if(window.DHPNProgress)window.DHPNProgress.recordMCQ("NHPC HA – General Medicine",[Q[state.index][0],Q[state.index][1],Q[state.index][2],Q[state.index][3],Q[state.index][4],Q[state.index][5]],idx);}else{state.answers[state.index]=idx;renderQuestion();}return;}
  if(b.dataset.haNext!==undefined){if(state.index===state.items.length-1)finish();else{state.index++;renderQuestion();}return;}
  if(b.dataset.haPrev!==undefined){state.index=Math.max(0,state.index-1);renderQuestion();return;}
  if(b.dataset.haPracticeNext!==undefined){if(state.index===Q.length-1){menu();return;}state.index++;renderPracticeQ();return;}
  if(b.dataset.haPracticePrev!==undefined){state.index=Math.max(0,state.index-1);renderPracticeQ();}
 });
 menu();
})();